## 9. `--format '{{ sql . }}'` output

Command shape: `/tmp/atlas_orig schema inspect -u "sqlite://<db>" --format '{{ sql . }}'`
Exit `0`, stderr empty. Output is a sequence of comment line + statement line per table/index,
each ending with `\n`; statements end with `;`. Identifiers are backtick-quoted. Tables in
creation order; each table's `CREATE TABLE` is followed immediately by its index statements.

### types.db

```sql
-- Create "all_types" table
CREATE TABLE `all_types` (`c_int` int NULL, `c_integer` integer NULL, `c_tinyint` tinyint NULL, `c_smallint` smallint NULL, `c_mediumint` mediumint NULL, `c_bigint` bigint NULL, `c_unsigned_big_int` unsigned big int NULL, `c_int2` int2 NULL, `c_int8` int8 NULL, `c_character` character NULL, `c_varchar` varchar NULL, `c_varying_character` varying character NULL, `c_nchar` nchar NULL, `c_native_character` native character NULL, `c_nvarchar` nvarchar NULL, `c_text` text NULL, `c_clob` clob NULL, `c_blob` blob NULL, `c_real` real NULL, `c_double` double NULL, `c_double_precision` double precision NULL, `c_float` float NULL, `c_numeric` numeric NULL, `c_decimal` decimal NULL, `c_boolean` boolean NULL, `c_date` date NULL, `c_datetime` datetime NULL, `c_time` time NULL, `c_timestamp` timestamp NULL, `c_json` json NULL, `c_uuid` uuid NULL, `c_foo` FOO NULL, `c_int11` int NULL, `c_varchar_nosize` varchar NULL);
```

Note: in SQL format **all size arguments are dropped** (`character`, `varchar`, `decimal` — no
`(20)`/`(255)`/`(10,5)`), multi-word types render with spaces (`unsigned big int`,
`varying character`, `double precision`), unknown types keep their spelling (`FOO`).

### pk.db

```sql
-- Create "t_int_pk" table
CREATE TABLE `t_int_pk` (`id` int NULL, `name` text NULL, PRIMARY KEY (`id`));
-- Create "t_integer_pk" table
CREATE TABLE `t_integer_pk` (`id` integer NULL, `name` text NULL, PRIMARY KEY (`id`));
-- Create "t_autoinc" table
CREATE TABLE `t_autoinc` (`id` integer NULL PRIMARY KEY AUTOINCREMENT, `name` text NULL);
-- Create "t_text_pk" table
CREATE TABLE `t_text_pk` (`id` text NULL, `name` text NULL, PRIMARY KEY (`id`));
-- Create "t_composite" table
CREATE TABLE `t_composite` (`a` int NULL, `b` text NULL, PRIMARY KEY (`a`, `b`));
```

The AUTOINCREMENT table inlines `PRIMARY KEY AUTOINCREMENT` on the column and has **no**
table-level `PRIMARY KEY`.

### defaults.db

```sql
-- Create "t_defaults" table
CREATE TABLE `t_defaults` (`c1` text NULL DEFAULT 'hello', `c2` text NULL DEFAULT 'it''s', `c3` text NULL DEFAULT 'say "hi"', `c4` int NULL DEFAULT -5, `c5` real NULL DEFAULT 3.14, `c6` text NULL DEFAULT (CURRENT_TIMESTAMP), `c7` int NULL DEFAULT (1+2), `c8` text NULL DEFAULT (NULL), `c9` blob NULL DEFAULT 'x''FF00''', `c10` text NULL DEFAULT 'with
newline', `c11` integer NULL DEFAULT 0, `c12` text NULL DEFAULT 'back\slash');
```

String defaults are single-quoted (`'` escaped as `''`; embedded newline stays a literal newline;
backslash NOT escaped); `sql(...)` defaults are wrapped in parentheses; the blob literal is
rendered as a quoted string `'x''FF00'''`.

### misc.db

```sql
-- Create "t_misc" table
CREATE TABLE `t_misc` (`a` text NOT NULL, `b` text NULL, `c` text NOT NULL, `d` int NULL AS (abs(-1)) VIRTUAL, `e` int NULL AS (1*2) STORED);
-- Create "t_unique_col" table
CREATE TABLE `t_unique_col` (`a` int NULL, `b` text NULL);
-- Create index "t_unique_col_a" to table: "t_unique_col"
CREATE UNIQUE INDEX `t_unique_col_a` ON `t_unique_col` (`a`);
-- Create "t_unique_idx" table
CREATE TABLE `t_unique_idx` (`a` int NULL, `b` text NULL);
-- Create index "idx_u" to table: "t_unique_idx"
CREATE UNIQUE INDEX `idx_u` ON `t_unique_idx` (`a`);
-- Create index "idx_n" to table: "t_unique_idx"
CREATE INDEX `idx_n` ON `t_unique_idx` (`b`);
```

Autoindex names (`sqlite_autoindex_*`) are **renamed** to `<table>_<column>` in SQL output;
explicit index names are kept. Index comments use `-- Create index "<name>" to table: "<table>"`.

### constraints.db

```sql
-- Create "parent" table
CREATE TABLE `parent` (`id` integer NULL, `code` text NULL, PRIMARY KEY (`id`));
-- Create index "parent_code" to table: "parent"
CREATE UNIQUE INDEX `parent_code` ON `parent` (`code`);
-- Create "child" table
CREATE TABLE `child` (`id` integer NULL, `parent_id` int NULL, `code` text NULL, `age` int NULL, PRIMARY KEY (`id`), CONSTRAINT `0` FOREIGN KEY (`code`) REFERENCES `parent` (`code`) ON UPDATE NO ACTION ON DELETE RESTRICT, CONSTRAINT `1` FOREIGN KEY (`parent_id`) REFERENCES `parent` (`id`) ON UPDATE SET NULL ON DELETE CASCADE, CHECK (age >= 0), CONSTRAINT `chk_age` CHECK (age < 150));
```

FKs keep their ordinal names as `CONSTRAINT \`0\``; actions render with spaces (`ON UPDATE NO
ACTION`, `ON DELETE SET NULL`); unnamed CHECKs render bare `CHECK (...)`, named ones
`CONSTRAINT \`name\` CHECK (...)`.

